def next_smallest_palindrome(n):
    # Convert the number to a string for easier manipulation
    n_str = str(n)
    n_len = len(n_str)

    # If the number is a palindrome or the first half of the next palindrome
    if n_str == n_str[::-1] or (n_str[:(n_len + 1) // 2] == n_str[:(n_len + 1) // 2 - 1:-1]):
        # Increment the number if it's a palindrome
        if n_str == n_str[::-1]:
            return n + 1
        # Find the next palindrome
        for i in range(n_len, 0, -1):
            if n_str[:i] == n_str[:i - 1:-1]:
                return int(n_str[:i] + n_str[i - 1] + n_str[i:])
    return None

