def find_solution(a, b, n):
    # If n is less than the greatest common divisor of a and b, no solution exists
    if n < abs(a * b) // gcd(a, b):
        return None
    # Extended Euclidean Algorithm to find x and y
    x, y, u, v = 1, 0, 0, 1
    while n != 0:
        if n < 0:
            q, r = divmod(-a, -n)
        else:
            q, r = divmod(a, n)
        a, n = n, r
        u, v = v, u - q * v
        x, y = y, x - q * y
    # Ensure x and y are positive
    if x < 0:
        x += b
    if y < 0:
        y += a
    return (x, y)

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a
